// src/pages/admin/Loans.js
import React, { useState, useEffect } from 'react';
import { loansAPI, clientsAPI } from '../../services/api';
import { Plus, Eye, Calendar } from 'lucide-react';
import LoanModal from '../../components/ui/LoanModal';
import LoanDetail from '../../components/ui/LoanDetail';

const fmtMoney = (n) => new Intl.NumberFormat('fr-FR').format(n || 0) + ' FCFA';
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('fr-FR') : '—';
const statusBadge = (s) => {
  const map = { ACTIVE: ['badge-info', 'Actif'], COMPLETED: ['badge-success', 'Soldé'], OVERDUE: ['badge-danger', 'En retard'] };
  const [cls, label] = map[s] || ['badge-gray', s];
  return <span className={`badge ${cls}`}>{label}</span>;
};

export default function Loans() {
  const [loans, setLoans] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState(null);
  const [selected, setSelected] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const res = await loansAPI.getAll();
      setLoans(res.data.data);
    } catch {}
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  return (
    <div className="fade-in">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24 }}>
        <div>
          <h1 style={{ fontSize: 22, marginBottom: 4 }}>Prêts</h1>
          <p style={{ color: 'var(--gray-500)', fontSize: 13 }}>{loans.length} prêt(s) au total</p>
        </div>
        <button className="btn btn-primary" onClick={() => setModal('add')}>
          <Plus size={15} /> Nouveau prêt
        </button>
      </div>

      <div className="card">
        <div className="table-wrap">
          {loading ? (
            <div className="page-loader"><div className="spinner" /></div>
          ) : loans.length === 0 ? (
            <div className="empty-state"><Calendar size={36} /><p>Aucun prêt enregistré</p></div>
          ) : (
            <table>
              <thead><tr>
                <th>Client</th><th>Montant</th><th>Taux</th><th>Durée</th><th>Total à payer</th><th>Date</th><th>Statut</th><th>Actions</th>
              </tr></thead>
              <tbody>
                {loans.map((l) => (
                  <tr key={l._id}>
                    <td style={{ fontWeight: 500 }}>{l.clientId?.name || '—'}</td>
                    <td>{fmtMoney(l.amount)}</td>
                    <td>{l.interestRate}%</td>
                    <td>{l.duration} mois</td>
                    <td style={{ fontWeight: 600, color: 'var(--primary)' }}>{fmtMoney(l.totalRepayable)}</td>
                    <td style={{ color: 'var(--gray-500)' }}>{fmtDate(l.startDate)}</td>
                    <td>{statusBadge(l.status)}</td>
                    <td>
                      <button className="btn btn-outline btn-icon btn-sm" title="Détails"
                        onClick={() => { setSelected(l); setModal('detail'); }}>
                        <Eye size={13} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {modal === 'add' && (
        <LoanModal onClose={() => setModal(null)} onSave={() => { setModal(null); load(); }} />
      )}
      {modal === 'detail' && selected && (
        <LoanDetail loan={selected} onClose={() => { setModal(null); setSelected(null); }} />
      )}
    </div>
  );
}
